-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.on_event_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.owner_id is not null or new.type = 'personal' then
    return new;
  end if;

  if new.community_ids is null or array_length(new.community_ids, 1) is null then
    perform public.notify_all(
      new.created_by, 'event', 'New event: ' || new.title,
      'A new event has been added to the calendar.',
      '/events?event=' || new.id
    );
  else
    insert into public.notifications (recipient_id, type, title, body, link)
    select distinct m.profile_id, 'event', 'New event: ' || new.title,
           'A new event has been added to the calendar.',
           '/events?event=' || new.id
    from public.community_members m
    join public.profiles p on p.id = m.profile_id
    where m.community_id = any (new.community_ids)
      and m.status = 'active'
      and p.status = 'active'
      and (new.created_by is null or m.profile_id <> new.created_by);
  end if;

  return new;
end;
$function$;
